import {createMarkingInboxUI} from './classroom-inbox-ui.mjs';
import {editableQuestions} from './quiz-authoring.mjs';
export function createLearningWorkflowUI({e,api,ui,link,quizzes,filesView}){
 const staff=()=>ui.actor().role!=='student';let timer=null,saveQueue=Promise.resolve(),generation=0,librarySearch='',bankItems=[];
 const markingInbox=createMarkingInboxUI({e,ui,link});
 const day=d=>d?new Date(d+'T12:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short'}):'No deadline';
 const taskLink=(a,label)=>link(label||a.title,{class:a.classId,assignment:a.id,...(a.studentId?{review:a.studentId}:{})});
 const status={assigned:'To do',draft:'In progress',overdue:'Overdue',feedback:'New feedback',submitted:'Turned in',returned:'Completed'};
 function nav(params){const view=params.get('view')||'today',active=params.has('help')||view==='help'?'updates':params.has('copyUnit')||params.has('publishUnit')||params.has('class')||params.has('assignment')?'classes':view==='insights'||view==='path'&&staff()?'progress':view==='path'?'grades':view;return '<nav class="learning-nav" aria-label="Learning workspace">'+[['today','Today'],['week','Week'],['updates','Updates'],['classes','Classrooms'],['portfolio','Portfolio'],...(staff()?[['inbox','To mark'],['drafts','Drafts'],['library','Library'],['progress','Progress']]:[['reading','My reading'],['grades','My progress']]),['guide','Help']].map(([v,t])=>'<a '+(active===v?'aria-current="page"':'')+' href="#/classroom?view='+v+'">'+t+(v==='updates'?'<span data-update-badge></span>':'')+'</a>').join('')+'</nav>';}
 async function dashboard(params){const d=await api('dashboard'+(params.get('date')?'?date='+encodeURIComponent(params.get('date')):'')),student=d.student,inbox=params.get('view')==='inbox';
  const cards=student?[['To do',d.summary.todo],['Overdue',d.summary.overdue],['New feedback',d.summary.feedback]]:[['To mark',d.summary.review],['Missing work',d.summary.missing],['Ready for MIS',d.summary.transfer]];
  const metrics='<div class="learning-stats">'+cards.map(([t,n])=>'<div><strong>'+n+'</strong><span>'+t+'</span></div>').join('')+'</div>';
  if(inbox)return markingInbox.page(d,params,metrics);
  const next=student?d.tasks.find(t=>t.status==='draft')||d.tasks.find(t=>t.status==='overdue')||d.tasks.find(t=>t.status==='feedback')||d.tasks.find(t=>t.status==='assigned'):d.inbox.find(t=>!t.returned&&!t.missing);
  const top='<p class="learning-week-link">'+link('View my weekly learning plan →',{view:'week',date:d.date})+(student?' · '+link('My learning path',{view:'path'}):'')+'</p><div class="learning-section-title"><h2>'+(student?'Your next steps':'Your teaching day')+'</h2><label>Day <input type="date" id="learning-date" value="'+d.date+'"></label></div>'+metrics+(next?'<div class="learning-next"><div><small>'+(student?'PICK UP WHERE YOU LEFT OFF':'NEXT TO REVIEW')+'</small><strong>'+e(next.title)+'</strong><span>'+e(student?next.subject:next.studentName)+'</span></div><a class="btn primary" href="#/classroom?'+new URLSearchParams({class:next.classId,assignment:next.id,...(!student?{review:next.studentId}:{})})+'">'+(student?(next.status==='feedback'?'Read feedback':next.status==='draft'?'Continue working':'Open task'):'Open work')+' →</a></div>':'');
  const tasks=student?d.tasks.filter(t=>!['submitted','returned'].includes(t.status)):d.tasks.filter(t=>t.review||t.missing).slice(0,12),table='<section class="vle-panel"><div class="learning-section-title"><h3>'+(student?'Work & feedback':'Classes needing attention')+'</h3><span>'+tasks.length+' tasks</span></div><div class="learning-task-list">'+tasks.map((t,index)=>(index===6?'<details class="learning-more-tasks"><summary>Show '+(tasks.length-6)+' more tasks</summary>':'')+'<a class="learning-task" href="#/classroom?'+new URLSearchParams({class:t.classId,assignment:t.id})+'"><span><strong>'+e(t.title)+'</strong><small>'+e(t.subject)+' · '+e(t.className)+'</small></span><span><small>'+day(t.due)+(t.minutes?' · '+t.minutes+' min':'')+'</small><b class="learning-tag '+(t.status==='overdue'?'overdue':'')+'">'+(student?status[t.status]:t.review+' to mark · '+t.missing+' missing')+'</b></span></a>'+((index===tasks.length-1&&tasks.length>6)?'</details>':'')).join('')+(tasks.length?'':'<p class="learning-empty">Everything is up to date. Open a classroom to explore its work.</p>')+'</div></section>';
  const lessons='<section class="vle-panel"><h3>Today’s lessons</h3><div class="learning-lessons">'+d.lessons.map(l=>'<div><span class="learning-period">'+e(l.period)+'</span><span>'+(l.classroom?link(l.className,{class:l.classId}):e(l.className))+'<small>'+e(l.from?l.from+'–'+l.to:l.start||l.time||'')+(l.room?' · '+e(l.room):'')+'</small></span></div>').join('')+(d.lessons.length?'':'<p>No lessons are scheduled for this date.</p>')+'</div></section>';
  return top+'<div class="learning-dashboard">'+table+lessons+'</div>'+(student?'<details class="vle-panel"><summary>Completed & turned-in work</summary>'+d.tasks.filter(t=>['submitted','returned'].includes(t.status)).map(t=>'<p>'+taskLink(t)+' <small>'+status[t.status]+'</small></p>').join('')+'</details>':'<p>'+link('Open marking inbox',{view:'inbox'})+' · '+link('Resume saved marking ('+(d.markingDrafts?.length||0)+')',{view:'inbox',status:'drafts'})+' · '+link('Browse teaching library',{view:'library'})+'</p>');
 }
 async function library(){const d=await api('library'),items=d.items.filter(i=>(i.title+' '+i.subject+' '+i.topic).toLowerCase().includes(librarySearch.toLowerCase()));return '<div class="learning-section-title"><h2>Teaching library</h2><label>Find resources <input id="learning-library-search" value="'+e(librarySearch)+'" placeholder="Title, subject or topic"></label></div><p>Save an assessment or a question from its page. Reuse it without changing the original. Department items are shared with teachers in the same curriculum area.</p><div class="learning-library-grid">'+items.map(row=>'<article class="vle-panel"><small>'+e(row.subject)+' · '+(row.kind==='question'?'Question bank':'Assessment template')+' · '+(row.shared?'Department':'Private')+'</small><h3>'+e(row.title)+'</h3><p>'+e(row.topic)+' · '+e(row.ownerName)+'</p><details><summary>Preview</summary><p class="vle-prose">'+e(row.content.description||row.content.questions?.map(q=>q.prompt).join('\n')||'')+'</p></details>'+(row.kind==='assessment'?'<form data-vle="reuse"><input type="hidden" name="libraryId" value="'+e(row.id)+'"><label class="vle-field">Copy to classroom<select name="classId">'+d.classes.map(c=>'<option value="'+e(c.id)+'">'+e(c.name)+'</option>').join('')+'</select></label><button class="btn" type="submit">Create editable copy →</button></form>':'<p class="muted">Add this from Bank in the quiz builder.</p>')+'</article>').join('')+'</div>'+(items.length?'':'<p class="learning-empty">Your library is ready. Open a saved assessment and choose Save to library to add your first reusable resource.</p>')+'<details class="vle-panel"><summary>My reusable feedback comments</summary><form data-vle="save-comments"><label class="vle-field">One comment per line<textarea name="comments" maxlength="30000">'+e(d.comments.join('\n'))+'</textarea></label><button type="submit" class="btn">Save comments</button></form></details>';}
 async function insights(params){const d=await api('insights'+(params.get('class')?'?classId='+encodeURIComponent(params.get('class')):'')),rows=d.assignments.flatMap(a=>a.questions.filter(q=>q.responses).map(q=>({...q,assignment:a}))).sort((a,b)=>a.percentage-b.percentage);return '<h2>Learning progress</h2><p>Question-level evidence from returned work. Scores below 60% identify questions to revisit; they are a prompt for teacher judgement.</p><div class="vle-panel table-wrap"><table class="data-table"><thead><tr><th>Objective / question</th><th>Assessment</th><th>Class result</th><th>Next step</th></tr></thead><tbody>'+rows.map(q=>'<tr><td><strong>'+e(q.objective||'Objective not tagged')+'</strong><small>'+e(q.prompt)+'</small></td><td>'+taskLink(q.assignment)+'<small>'+e(q.assignment.className)+'</small></td><td>'+q.percentage+'%<small>'+q.responses+' reviewed responses</small></td><td><details><summary>'+q.support.length+' students may need practice</summary>'+q.support.map(s=>'<p>'+link(s.name,{class:q.assignment.classId,assignment:q.assignment.id,review:s.id})+'</p>').join('')+'</details>'+(q.support.length?'<button type="button" class="text-button" data-practice-question="'+q.id+'" data-assignment="'+e(q.assignment.id)+'">Create practice draft</button>':'')+'</td></tr>').join('')+'</tbody></table>'+(rows.length?'':'<p class="learning-empty">Return marked quizzes to see question results and learning objectives here.</p>')+'</div>';}
 function optionsEditor(a,people=[],units=[]){const l=a.learning||{},quiz=a.kind==='quiz'||a.questions,criteria=l.rubric||[];return '<details class="vle-panel learning-options"><summary>Options · objectives, release & individual support'+(!quiz?', rubric':'')+'</summary><label class="vle-field">Course unit<select name="unitId"><option value="">No unit / general classwork</option>'+units.map(u=>'<option value="'+e(u.id)+'" '+(l.unitId===u.id?'selected':'')+'>'+e(u.title)+'</option>').join('')+'</select></label><div class="vle-form-grid"><label class="vle-field">Estimated work time (minutes)<input name="estimatedMinutes" type="number" min="0" max="240" value="'+(l.estimatedMinutes||0)+'"></label><label class="vle-field">Release on (school time)<input name="openAt" type="datetime-local" value="'+(l.openAt?new Date(Date.parse(l.openAt)+5*3600000).toISOString().slice(0,16):'')+'"></label></div><label class="vle-field">Learning objectives (one per line)<textarea name="learningObjectives" maxlength="2000">'+e((l.objectives||[]).join('\n'))+'</textarea></label><details class="learning-individual"><summary>Assign to selected students / individual deadlines</summary><p>Leave all selections clear to assign to everyone. Individual deadlines are private.</p><div class="learning-student-options">'+people.map(p=>'<div><label><input type="checkbox" data-audience="'+e(p.id)+'" '+(l.audience?.includes(p.id)?'checked':'')+'> '+e(p.name)+'</label><label>Deadline <input type="date" data-extension="'+e(p.id)+'" value="'+e(l.extensions?.[p.id]||'')+'"></label></div>').join('')+'</div></details>'+(!quiz?'<div class="learning-rubric-editor"><h3>Marking rubric <small>Optional</small></h3><p>Give each criterion clear levels. The highest levels set the assignment’s total points.</p><div data-rubric-criteria>'+criteria.map(criterionEditor).join('')+'</div><button type="button" class="btn" data-rubric-add>＋ Add criterion</button></div>':'')+'</details>';}
 function criterionEditor(r={title:'',levels:[{label:'Beginning',points:0},{label:'Developing',points:2},{label:'Secure',points:4}]}){return '<fieldset data-rubric-criterion><legend>Criterion</legend><label class="vle-field">What are you assessing?<input data-rubric-title value="'+e(r.title)+'" maxlength="160" required></label><div class="learning-rubric-levels">'+r.levels.map(l=>'<div data-rubric-level><label>Level description<input data-level-label maxlength="200" value="'+e(l.label)+'" required></label><label>Points<input data-level-points type="number" min="0" max="10000" step="any" value="'+l.points+'" required></label><button type="button" data-level-remove aria-label="Remove level">×</button></div>').join('')+'</div><button type="button" class="text-button" data-level-add>＋ Add level</button> <button type="button" class="text-button" data-criterion-remove>Remove criterion</button></fieldset>';}
 function readLearning(f){const value=n=>f.elements[n]?.value||'',open=value('openAt');return{unitId:value('unitId'),estimatedMinutes:Number(value('estimatedMinutes')||0),objectives:value('learningObjectives').split('\n').map(s=>s.trim()).filter(Boolean),openAt:open?new Date(open+':00+05:00').toISOString():'',audience:[...f.querySelectorAll('[data-audience]:checked')].map(x=>x.dataset.audience),extensions:Object.fromEntries([...f.querySelectorAll('[data-extension]')].filter(x=>x.value).map(x=>[x.dataset.extension,x.value])),rubric:[...f.querySelectorAll('[data-rubric-criterion]')].map(r=>({title:r.querySelector('[data-rubric-title]').value,levels:[...r.querySelectorAll('[data-rubric-level]')].map(l=>({label:l.querySelector('[data-level-label]').value,points:Number(l.querySelector('[data-level-points]').value)}))}))};}
 function rubricReview(a,s){return a.learning?.rubric?.length?'<section class="learning-rubric-review"><h3>Mark with rubric</h3>'+a.learning.rubric.map(r=>'<fieldset><legend>'+e(r.title)+'</legend>'+r.levels.map(l=>'<label><input type="radio" name="rubric-'+r.id+'" data-rubric-mark="'+r.id+'" value="'+l.points+'" '+(s?.rubricMarks?.[r.id]===l.points?'checked':'')+' required><span>'+e(l.label)+'<strong>'+l.points+' points</strong></span></label>').join('')+'</fieldset>').join('')+'</section>':'';}
 function studentExtras(a,s){return(a.learning?.rubric?.length?'<details class="vle-panel"><summary>What success looks like · marking rubric</summary>'+a.learning.rubric.map(r=>'<h4>'+e(r.title)+'</h4><ul>'+r.levels.map(l=>'<li>'+e(l.label)+' — '+l.points+' points</li>').join('')+'</ul>').join('')+'</details>':'')+(a.learning?.objectives?.length?'<details class="vle-panel"><summary>What you are learning</summary><ul>'+a.learning.objectives.map(t=>'<li>'+e(t)+'</li>').join('')+'</ul></details>':'')+(s?.returnedAt?'<div class="learning-feedback-action">'+(!s.feedbackReadAt?'<button type="button" class="btn" data-feedback-read="'+e(a.id)+'" data-revision="'+s.revision+'">✓ I have read my feedback</button>':'<span>✓ Feedback read</span>')+(s.rubricMarks?'<details><summary>Your rubric feedback</summary>'+a.learning.rubric.map(r=>'<p><strong>'+e(r.title)+'</strong>: '+e(r.levels.find(l=>l.points===s.rubricMarks[r.id])?.label||'')+' · '+s.rubricMarks[r.id]+' points</p>').join('')+'</details>':'')+'</div>':'')+(s?.history?.length?'<details class="vle-panel"><summary>Earlier feedback & versions ('+s.history.length+')</summary>'+s.history.map(h=>'<article><strong>'+day(h.returnedAt?.slice(0,10))+' · '+h.mark+' / '+a.maximum+'</strong><p class="vle-prose">'+e(h.feedback||'')+'</p><p class="vle-prose">'+e(h.answer||Object.entries(h.answers||{}).map(([k,v])=>k+': '+(typeof v==='string'?v:'Response saved')).join('\n'))+'</p></article>').join('')+'</details>':'');}
 const reflection=s=>'<details class="learning-reflection-panel"><summary>Reflection / changes (optional)</summary><label class="vle-field learning-reflection">Reflection / what I changed (optional)<textarea name="reflection" maxlength="3000" placeholder="Explain how you used your teacher’s feedback.">'+e(s?.reflection||'')+'</textarea></label></details>';
 const saveStatus=()=>'<span class="learning-save-status" role="status" data-save-status>Changes save automatically while you work.</span>';
 function tools(a){return '<details class="vle-panel learning-library-save"><summary>Save to teaching library</summary><form data-vle="save-library"><input type="hidden" name="assignmentId" value="'+e(a.id)+'"><label class="vle-field">Resource name<input name="title" maxlength="160" value="'+e(a.title)+'" required></label><label><input type="checkbox" name="shared"> Share with my department</label><button class="btn" type="submit">Save reusable assessment</button></form></details>';}
 function history(s){return s?.history?.length?'<details class="vle-panel"><summary>Earlier returned versions ('+s.history.length+')</summary>'+s.history.map(h=>'<p><strong>'+h.mark+' points · '+e(new Date(h.returnedAt).toLocaleDateString('en-GB'))+'</strong></p><p class="vle-prose">'+e(h.feedback||'')+'</p><p class="vle-prose">'+e(h.answer||'Quiz responses saved in this version.')+'</p>').join('')+'</details>':'';}
 async function bind(root){
  markingInbox.bind(root);root.querySelector('#learning-library-search')?.addEventListener('change',ev=>{librarySearch=ev.target.value;ui.render();});root.querySelector('#learning-date')?.addEventListener('change',ev=>{location.hash='/classroom?view=today&date='+ev.target.value;});
  root.querySelectorAll('[data-practice-question]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{const r=await api('create-practice',{id:b.dataset.assignment,questionId:b.dataset.practiceQuestion});location.hash='/classroom?'+new URLSearchParams({class:r.result.classId,quizEditor:r.result.id});}catch(error){ui.toast(error.message);b.disabled=false;}}));
  root.querySelectorAll('[data-review-expand]').forEach(b=>b.addEventListener('click',()=>{const cards=root.querySelectorAll('.learning-review-question'),open=[...cards].some(d=>!d.open);cards.forEach(d=>d.open=open);b.textContent=open?'Collapse reviewed answers':'Expand all answers';}));
  root.querySelectorAll('[data-feedback-read]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await api('feedback-read',{id:b.dataset.feedbackRead,expectedRevision:Number(b.dataset.revision)});b.textContent='✓ Feedback read';}catch(error){ui.toast(error.message);b.disabled=false;}}));
  root.querySelectorAll('.learning-options').forEach(panel=>{const f=panel.closest('form'),criteria=panel.querySelector('[data-rubric-criteria]');if(!criteria)return;const total=()=>{const rows=readLearning(f).rubric,field=f.elements.maximum;if(field){field.readOnly=rows.length>0;if(rows.length)field.value=rows.reduce((n,r)=>n+Math.max(0,...r.levels.map(l=>l.points)),0);}};panel.addEventListener('input',total);panel.addEventListener('click',ev=>{const b=ev.target.closest('[data-rubric-add],[data-level-add],[data-level-remove],[data-criterion-remove]');if(!b)return;if(b.hasAttribute('data-rubric-add')){if(criteria.children.length>=12)return;criteria.insertAdjacentHTML('beforeend',criterionEditor());}else{const c=b.closest('[data-rubric-criterion]');if(b.hasAttribute('data-criterion-remove'))c.remove();else if(b.hasAttribute('data-level-remove')){if(c.querySelectorAll('[data-rubric-level]').length>2)b.closest('[data-rubric-level]').remove();}else if(c.querySelectorAll('[data-rubric-level]').length<6)c.querySelector('.learning-rubric-levels').insertAdjacentHTML('beforeend','<div data-rubric-level><label>Level description<input data-level-label required maxlength="200"></label><label>Points<input data-level-points type="number" min="0" max="10000" step="any" required></label><button type="button" data-level-remove aria-label="Remove level">×</button></div>');}total();ui.dirty(true);});total();});
  root.querySelectorAll('[data-workload-check]').forEach(b=>b.addEventListener('click',async()=>{const f=b.closest('form'),date=f.elements.due?.value,box=f.querySelector('[data-workload-result]');if(!date){box.textContent='Choose a deadline first.';return;}try{const d=await api('workload?'+new URLSearchParams({classId:f.elements.classId.value,date})),max=Math.max(0,...d.rows.map(r=>r.tasks)),minutes=Math.max(0,...d.rows.map(r=>r.minutes));box.textContent='Before this task: up to '+max+' other task(s) and '+minutes+' estimated minutes due for students in this class. Existing tasks without estimates are still counted.';}catch(error){box.textContent=error.message;}}));
  root.querySelectorAll('[data-save-bank-question]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await api('save-library',{assignmentId:b.dataset.assignment,kind:'question',questionId:b.dataset.saveBankQuestion});b.textContent='✓ Saved in my bank';}catch(error){ui.toast(error.message);b.disabled=false;}}));
  const commentSelect=root.querySelector('[data-comment-picker]');if(commentSelect){try{const d=await api('library');if(commentSelect.isConnected)commentSelect.innerHTML='<option value="">Insert saved feedback…</option>'+d.comments.map(c=>'<option value="'+e(c)+'">'+e(c.slice(0,90))+'</option>').join('');}catch{}commentSelect.addEventListener('change',()=>{const f=commentSelect.closest('form'),field=f.elements.feedback;if(commentSelect.value){field.value+=(field.value?'\n':'')+commentSelect.value;ui.dirty(true);commentSelect.value='';}});}
  root.querySelectorAll('form[data-vle="submit"],form[data-vle="quiz-submit"],form[data-vle="portfolio-save"]').forEach(f=>{if(f.querySelector('[value="unsubmit"]'))return;let changed=0;f.addEventListener('input',()=>{if(f.dataset.submitting)return;changed=++generation;const badge=f.querySelector('[data-save-status]');if(badge)badge.textContent='Unsaved changes…';clearTimeout(timer);timer=setTimeout(()=>{timer=null;saveQueue=saveQueue.then(async()=>{if(!f.isConnected)return;const mine=changed;try{if(badge)badge.textContent='Saving…';const data=Object.fromEntries(new FormData(f));data.expectedRevision=Number(data.expectedRevision);data.draft=true;if(f.dataset.vle==='portfolio-save')data.status='draft';delete data.intent;delete data.uploads;if(f.dataset.vle==='quiz-submit')data.answers=await quizzes.readAnswers(f);else data.files=await readFiles(f.querySelector('[name=uploads]'));if(!f.isConnected)return;const r=await api(f.dataset.vle,data);if(f.isConnected){f.elements.expectedRevision.value=r.result.revision;if(f.dataset.vle==='portfolio-save')f.elements.id.value=r.result.id;const state=f.closest('.vle-panel')?.querySelector('.vle-status');if(state)state.textContent='In progress';if(mine===generation){ui.dirty(false);if(badge)badge.textContent='✓ Saved '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});}else if(badge)badge.textContent='Saving latest changes…';}}catch(error){if(badge?.isConnected)badge.textContent='Not saved: '+error.message;ui.dirty(true);}});},1400);});});
 }
 async function readFiles(input){if(!input?.files?.length)return undefined;return Promise.all([...input.files].map(f=>new Promise((resolve,reject)=>{if(input.files.length>3||f.size>1048576){reject(Error('Use up to 3 files, each 1 MB or smaller.'));return;}const r=new FileReader();r.onerror=()=>reject(Error('Could not read '+f.name));r.onload=()=>resolve({name:f.name,data:String(r.result).split(',')[1]});r.readAsDataURL(f);})));}
 async function flushForHelp(root){if(ui.actor().role!=='student')return true;const f=root.querySelector('form[data-vle="submit"],form[data-vle="quiz-submit"]');if(!f||f.querySelector('[value="unsubmit"]'))return true;f.inert=true;f.dataset.submitting='true';try{await beforeSubmit();if(!f.isConnected)return false;if(!ui.isDirty?.())return true;const data=Object.fromEntries(new FormData(f));data.expectedRevision=Number(data.expectedRevision);data.draft=true;delete data.intent;delete data.uploads;if(f.dataset.vle==='quiz-submit')data.answers=await quizzes.readAnswers(f);else data.files=await readFiles(f.querySelector('[name=uploads]'));const r=await api(f.dataset.vle,data);if(!f.isConnected)return false;f.elements.expectedRevision.value=r.result.revision;ui.dirty(false);return true;}finally{f.inert=false;delete f.dataset.submitting;}}
 async function beforeSubmit(){clearTimeout(timer);timer=null;await saveQueue;}
 function release(){clearTimeout(timer);timer=null;generation++;}
 return{nav,dashboard,library,insights,optionsEditor,readLearning,rubricReview,studentExtras,reflection,saveStatus,tools,history,bind,beforeSubmit,flushForHelp,release};
}
